  const rowAfter = `| ${item.catalogNo} | *${item.book}* | ${item.author} | ${label} | **DB'DE KAYITLI / V2** | ${item.listNo} | 1 |`;
  if (catalog.includes(rowBefore)) catalog = catalog.replace(rowBefore, rowAfter);
